def cart_total_with_shipping(items, shipping, session=None):
    total = 0
    for item in (items or []):
        if isinstance(item, dict):
            p = item['price'] if 'price' in item and item['price'] is not None else 0
            q = item['quantity'] if 'quantity' in item and item['quantity'] is not None else 1
            total += p * q
    return total + shipping
